def parse_writer_result(path: Path) -> WriterResult:
    """Read an architecture writer result file, validate it against WRITER_SCHEMA_PATH and type it.

    A read failure (OSError) propagates unchanged.

    Returns:
        The validated WriterResult.

    Raises:
        TypeError: path is not a Path.
        ValueError: The file is not JSON or breaks the schema; the message names the file.

    """
    if not isinstance(path, Path):
        message: str = "parse_writer_result requires a Path"
        raise TypeError(message)
    decoded: object = _validated(path, WRITER_SCHEMA_PATH)
    try:
        return _build_writer_result(decoded, str(path))
    except TypeError as error:
        message = f"{path}: {error}"
        raise ValueError(message) from error


